-- Migração pontual: corrige o status de processos BDR/4608 que já estão
-- encerrados na planilha de origem (LegalDesk), mas ainda constavam como
-- "ativo" (ou outro status) no FaroLex. Só mexe em status — não altera
-- fase, valor, observação nem qualquer outro campo.

begin;

create temporary table planilha_bdr_encerrados (cnj text primary key) on commit drop;


update processos p
set status = 'encerrado'
from planilha_bdr_encerrados pl
where regexp_replace(p.numero_cnj, '\D', '', 'g') = pl.cnj
  and p.status <> 'encerrado';

-- resumo: quantos processos batem pelo CNJ e como ficou o status deles
select
  (select count(*) from planilha_bdr_encerrados) as linhas_planilha,
  (select count(*) from processos p join planilha_bdr_encerrados pl
     on regexp_replace(p.numero_cnj, '\D', '', 'g') = pl.cnj) as processos_encontrados,
  (select count(*) from processos p join planilha_bdr_encerrados pl
     on regexp_replace(p.numero_cnj, '\D', '', 'g') = pl.cnj
     where p.status = 'encerrado') as processos_encerrados_agora;

commit;
